from pathlib import Path
from playwright.sync_api import sync_playwright
from html import escape
from base64 import b64encode

root=Path(__file__).resolve().parents[1]
docs=root/'docs'
docs.mkdir(exist_ok=True)
images=docs/'screenshots'
images.mkdir(exist_ok=True)

css='''
:root{--green:#0E3B2E;--mint:#A7E3D0;--cream:#FBFAF6;--sand:#F1EADC;--dark:#202622;--muted:#72766F;--border:#D8DED6}
*{box-sizing:border-box}body{margin:0;font-family:"NanumSquare","Noto Sans CJK KR","Arial",sans-serif;background:var(--cream);color:var(--dark)}
.bar{height:63px;background:#fffdf8;border-bottom:1px solid #dde5de;display:flex;align-items:center;padding:0 60px;justify-content:space-between}
.brand{display:flex;align-items:center;gap:10px;color:var(--green);font-size:20px;font-weight:900;letter-spacing:-1px}.logo{width:32px;height:32px;background:var(--green);border-radius:9px;color:var(--mint);display:grid;place-items:center;font-size:18px}.brand small{display:block;font-size:8px;color:#8b918a;letter-spacing:2px;margin-top:2px}
nav{display:flex;gap:23px;align-items:center;font-size:12px;font-weight:800;color:#4d5b53}.topbtn{background:var(--green);color:#fff;padding:11px 16px;border-radius:22px}
.notice{height:30px;background:#e1f2e9;text-align:center;color:#266a50;font-size:11px;font-weight:700;line-height:30px}
.hero{background:var(--green);padding:70px 64px 80px;color:#fff;display:flex;gap:55px;min-height:520px;align-items:center}
.heroleft{width:55%}.hero h1{font-size:60px;line-height:1.21;letter-spacing:-4px;margin:20px 0}.hero h1 em{color:var(--mint);font-style:normal}.hero p{font-size:15px;line-height:1.9;color:#d4e8df;max-width:550px}.pill{display:inline-flex;border-radius:30px;border:1px solid #468373;color:var(--mint);padding:9px 14px;font-size:11px;font-weight:800;background:#ffffff0e}
.buttons{display:flex;gap:12px;margin-top:30px}.btn{padding:13px 22px;border-radius:30px;font-size:12px;font-weight:900}.btn.mint{background:var(--mint);color:var(--green)}.btn.outline{border:1px solid #6d988a;color:#fff}.visual{width:43%;min-height:330px;border:1px solid #4b806b;background:#ffffff10;border-radius:32px;display:grid;place-items:center;position:relative}.visual img{max-width:96%;height:300px}.flag{position:absolute;bottom:19px;right:20px;color:#d5ece2;background:#1a4132;padding:8px 12px;border-radius:7px;font-size:10px}
.metrics{margin-top:34px;display:flex;gap:33px;color:#d9e8df;font-size:10px}.metrics b{font-size:22px;color:var(--mint);display:block;margin-bottom:5px}
.below{padding:52px 64px}.eyebrow{color:var(--green);font-size:10px;font-weight:900;letter-spacing:2px}.below h2{font-size:29px;letter-spacing:-1.5px;margin:14px 0}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:25px}.card{background:#fff;border:1px solid var(--border);border-radius:22px;padding:23px;box-shadow:0 3px 13px #00000008}.card h3{font-size:16px;margin:9px 0}.card p{font-size:12px;line-height:1.7;color:var(--muted)}.num{color:#367c65;font-size:11px;font-weight:900}
.admin{display:flex;min-height:807px}.sidebar{width:250px;flex:none;background:var(--dark);color:#fff;padding:26px 17px}.sidebar .sidebrand{font-size:14px;font-weight:900;display:flex;gap:9px;color:#fff;align-items:center;padding-left:8px}.shield{color:var(--mint);font-size:19px}.sidebar .small{font-size:9px;margin:7px 0 29px 37px;color:#abb2aa}.sideitem{border-radius:11px;display:flex;align-items:center;gap:12px;margin:3px 0;padding:13px 16px;color:#bbbfb9;font-size:12px;font-weight:800}.sideitem span{font-size:16px;width:16px;text-align:center;color:#8da99b}.sideitem.selected{background:var(--green);color:var(--mint)}.sideitem.selected span{color:var(--mint)}.sidefoot{margin-top:105px;padding:16px 9px 0;border-top:1px solid #50554f;color:#b3b9b2;font-size:11px;line-height:1.7}
.adminbody{flex:1;padding:27px 30px;background:#f6f3ea;min-width:0}.warning{background:#fff9e9;border:1px solid #e6dbbb;color:#87632b;border-radius:11px;padding:11px 16px;font-size:11px;margin-bottom:23px}.welcome{border:1px solid var(--border);background:#fff;border-radius:24px;padding:24px 26px;display:flex;justify-content:space-between;align-items:center}.welcome h1{font-size:23px;margin:0 0 9px}.welcome p{font-size:12px;color:var(--muted);margin:0}.session{border:1px solid #c1e6cb;background:#ebf8f0;border-radius:12px;padding:10px 12px;color:#26804f;font-size:10px;font-weight:900}.statgrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin-top:23px}.stat{background:#fff;border:1px solid var(--border);border-radius:19px;padding:20px;min-width:0}.stat small{display:block;color:var(--muted);font-size:11px}.stat strong{display:block;font-size:26px;margin:12px 0 4px}.stat .more{font-size:10px;color:var(--green);font-weight:900}.duo{display:grid;grid-template-columns:1fr 1fr;gap:19px;margin-top:22px}.panel{border:1px solid var(--border);background:#fff;border-radius:22px;padding:23px}.panel h2{font-size:14px;margin:0 0 14px}.row{display:flex;justify-content:space-between;border-top:1px solid #e9ece7;align-items:center;padding:14px 0}.row b{display:block;font-size:12px}.row small{display:block;margin-top:6px;font-size:10px;color:var(--muted)}.status{border-radius:8px;background:#fff7e6;color:#996e21;font-size:10px;padding:5px 8px;font-weight:800}.status.ok{background:#e7f7ef;color:#31835a}
.screenhead{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d6ddd6;padding:5px 0 19px;margin-bottom:21px}.screenhead h1{font-size:23px;margin:0 0 9px}.screenhead p{color:var(--muted);font-size:11px;margin:0}.add{background:var(--green);color:#fff;font-size:11px;font-weight:850;padding:12px 16px;border-radius:10px}
.editors{display:grid;grid-template-columns:7fr 5fr;gap:22px;align-items:start}.editor{background:#fff;border:1px solid var(--border);border-radius:22px;padding:23px}.editor h2{font-size:14px;border-bottom:1px solid var(--border);padding-bottom:14px;margin:0 0 18px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:15px}.field label{font-size:11px;color:#294e39;font-weight:850;display:block;margin-bottom:9px}.input{height:39px;border:1px solid var(--border);background:var(--cream);border-radius:9px;line-height:39px;padding:0 11px;color:#667067;font-size:11px}.input.big{height:85px;line-height:1.7;padding-top:10px}.wide{grid-column:span 2}.preview{height:205px;border-radius:17px;overflow:hidden;display:grid;grid-template-columns:1fr 1fr;margin:17px 0}.preview>div{display:grid;place-items:center;letter-spacing:3px;font-size:11px;color:#315e4f;font-weight:900}.preview>div:first-child{background:linear-gradient(145deg,#e3e9df,#bfcdc5)}.preview>div:last-child{background:linear-gradient(145deg,#dceee2,#a7e3d0)}.editor h3{font-size:16px;margin:12px 0}.editor .summary{font-size:11px;line-height:1.7;color:var(--muted)}
.footnote{position:fixed;right:18px;bottom:13px;color:#82938a;font-size:9px;opacity:.85}
'''
menus=[('▦','대시보드 홈','dashboard'),('✎','견적 문의 관리','inquiries'),('▣','상담 예약 관리','reservations'),('▤','Q&A 답변 관리','qna'),('▧','시공 사례 관리','cases'),('▥','서비스 정보 관리','services'),('?','자주묻는질문 관리','faqs'),('▧','이미지 에셋 관리','assets'),('⚙','사이트 기본 설정','settings')]
def top():
 return '''<div class="notice">PUBLIC UI DEMO · 실제 업체가 아닌 공개용 디자인 예시이며 상담·결제·예약 기능이 없습니다.</div><header class="bar"><div class="brand"><span class="logo">집</span><div>샘플 홈케어<small>HOMECARE DESIGN TEMPLATE</small></div></div><nav><span>홈</span><span>서비스</span><span>작업 사례</span><span>FAQ</span><span>작업 일지</span><span>Q&A</span><span>관리 화면</span><span class="topbtn">문의 UI 체험 ↗</span></nav></header>'''
def sidebar(screen):
 return '''<div class="sidebar"><div class="sidebrand"><span class="shield">◈</span>샘플 홈케어 ADMIN</div><div class="small">관리자 통합 제어 대시보드 · UI ONLY</div>'''+''.join(f'<div class="sideitem {"selected" if v==screen else ""}"><span>{sym}</span>{name}</div>' for sym,name,v in menus)+'''<div class="sidefoot"><b style="color:#a7e3d0">PUBLIC UI DEMO</b><br>실제 계정 권한이나 고객 데이터는 연결되지 않았습니다.</div></div>'''
def intro_admin():return '<div class="warning"><b>데모 환경:</b> 모든 항목은 가상의 샘플이며 저장·전송·운영 기능을 포함하지 않습니다.</div>'
def landing():
 return top()+'''<section class="hero"><div class="heroleft"><span class="pill">● 예시 지역 · 홈케어 서비스 디자인</span><h1>더 편안한 공간을 위한<br><em>세심한 관리</em></h1><p>실제 업체 정보 대신 가상 콘텐츠를 담은 홈케어 웹사이트 디자인 템플릿입니다. 방문 서비스의 안내 흐름과 화면 구성, 재사용 가능한 UI 패턴을 소개합니다.</p><div class="buttons"><span class="btn mint">서비스 문의 화면 ↗</span><span class="btn outline">예약 UI 체험</span><span class="btn outline">작업 사례 보기</span></div><div class="metrics"><div><b>04</b>서비스 카테고리</div><div><b>03</b>가상 작업 사례</div><div><b>100%</b>샘플 콘텐츠</div></div></div><div class="visual"><img src="../public/illustrations/home-scene.svg"><div class="flag">샘플 SVG 일러스트 · DEMO</div></div></section><section class="below"><span class="eyebrow">01 / WHY IT MATTERS</span><h2>공간 관리가 필요한 순간을 쉽게 설명합니다</h2><div class="cards">'''+''.join(f'<div class="card"><span class="num">0{i+1} / SERVICE</span><h3>{n}</h3><p>{d}</p></div>' for i,(n,d) in enumerate([('욕실·타일 관리','공간 마감 상태를 살펴보는 서비스 소개 카드'),('에어컨 관리','가전 관리 범위를 이해하기 쉬운 카드'),('세탁기 관리','관리 순서와 작업 범위를 보여주는 카드'),('패브릭 케어','소재별 관리 항목을 안내하는 카드')]))+'</div></section>'
def dashboard():
 cards=[('대기 견적 문의','2건','/ 총 3건'),('대기 예약 신청','2건','/ 총 3건'),('미답변 Q&A 질문','1건','/ 총 2건'),('미검토 작업 사례','1건','/ 총 3건')]
 def panel(title,rows):
  return '<div class="panel"><h2>'+title+' <span style="float:right;color:var(--muted);font-weight:400;font-size:11px">전체 보기 →</span></h2>'+''.join(f'<div class="row"><div><b>{name} ({loc})</b><small>{desc}</small></div><span class="status {"ok" if state=="완료" else ""}">{state}</span></div>' for name,loc,desc,state in rows)+'</div>'
 return top()+'<div class="admin">'+sidebar('dashboard')+'<div class="adminbody">'+intro_admin()+'''<div class="welcome"><div><h1>샘플 홈케어 마스터 대시보드</h1><p>견적 접수, 상담 일정 조율 및 Q&A 답변 관리 화면의 디자인 시연입니다.</p></div><div class="session">✓ UI DEMO SESSION</div></div><div class="statgrid">'''+''.join(f'<div class="stat"><small>{title}</small><strong>{count} <span style="font-size:10px;color:var(--muted)">{total}</span></strong><span class="more">자세히 보기 →</span></div>' for title,count,total in cards)+'''</div><div class="duo">'''+panel('최근 접수된 견적 문의',[('샘플 고객 A','가상 지역 A','욕실 케어 · 2026-10-09','접수'),('샘플 고객 B','가상 지역 B','가전 관리 · 2026-10-11','확인중'),('샘플 고객 C','가상 지역 C','패브릭 케어 · 2026-10-12','완료')])+panel('최근 접수된 예약 현황',[('샘플 예약 A','가상 지역 A','2026-10-22 · 오전','접수'),('샘플 예약 B','가상 지역 C','2026-10-23 · 오후','확인중'),('샘플 예약 C','가상 지역 B','2026-10-25 · 오후','완료')])+'''</div><div class="duo"><div class="panel"><h2>콘텐츠 운영 현황</h2><p class="summary">작업 사례 3개 · 등록 서비스 4개 · FAQ 4개</p></div><div class="panel"><h2>디자인 검증 안내</h2><p class="summary">이 관리자 UI는 실제 운영 상태가 아닌 가상 데이터 예시입니다.</p></div></div></div></div>'''
def cases():
 fields=[('사례 제목 *','샘플 시공 사례'),('지역 *','가상 지역 D'),('시공 유형 *','욕실 케어'),('공개 상태','비공개 (초기값)'),('발견된 문제점 *','작업 전 상태를 기록하는 예시 설명입니다.'),('시공 조치 내용 *','단계별 점검 및 관리 내용을 작성합니다.'),('결과 한줄 요약 *','전후 카드 비교를 위한 예시 텍스트'),('시공 전 이미지 경로','샘플 이미지 영역'),('시공 후 이미지 경로','샘플 이미지 영역')]
 editor='<div class="editor"><h2>시공 사례 에디터 양식 <span style="float:right;color:#849086;font-size:11px">× 닫기</span></h2><div class="fields">'+''.join('<div class="field"><label>'+lbl+'</label><div class="input '+('big' if i in [4,5,6] else '')+'">'+val+'</div></div>' for i,(lbl,val) in enumerate(fields))+'</div><div class="buttons"><span class="btn" style="background:var(--sand);color:var(--green)">욕실 케어 예문 삽입</span><span class="btn mint">사례 등록 (데모)</span></div></div>'
 preview='''<div class="editor"><h2>실시간 웹사이트 카드 미리보기</h2><div class="preview"><div>BEFORE</div><div>AFTER</div></div><span style="font-size:10px;border-radius:6px;padding:7px;background:#e9f5ee;color:#0E3B2E">욕실 케어</span><h3>샘플 시공 사례</h3><p class="summary">전후 카드 비교를 위한 예시 텍스트</p><p style="font-size:10px;color:var(--muted);margin-top:24px">실제 사진을 사용하지 않은 자리 표시용 그래픽</p></div>'''
 return top()+'<div class="admin">'+sidebar('cases')+'<div class="adminbody">'+intro_admin()+'''<div class="screenhead"><div><h1>시공 작업 사례 관리</h1><p>Before / After 작업 사례와 게시 상태, 카드 미리보기를 관리하는 UI 데모</p></div><span class="add">+ 신규 사례 추가</span></div><div class="editors">'''+editor+preview+'</div></div></div>'

sample={'home':landing,'admin':dashboard,'cases':cases}
with sync_playwright() as p:
    b=p.chromium.launch(executable_path='/usr/bin/chromium', headless=True, args=['--no-sandbox','--disable-dev-shm-usage'])
    page=b.new_page(viewport={'width':1440,'height':980},device_scale_factor=1)
    for name,build in sample.items():
        body=build()
        html=f'<!doctype html><html lang="ko"><head><meta charset="utf-8"><title>{escape(name)} UI preview fixture</title><style>{css}</style></head><body>{body}<div class="footnote">STATIC UI COMPOSITION / DEMO ONLY</div></body></html>'
        fixture=docs/f'preview-fixture-{name}.html'
        fixture.write_text(html,encoding='utf-8')
        local_src = "../public/illustrations/home-scene.svg"
        payload = b64encode((root / "public/illustrations/home-scene.svg").read_bytes()).decode("ascii")
        page.set_content(html.replace(local_src, "data:image/svg+xml;base64,"+payload), wait_until="domcontentloaded")
        page.wait_for_timeout(250)
        page.screenshot(path=str(images/f'{name}.png'),full_page=False,animations='disabled')
        print(name, (images/f'{name}.png').stat().st_size)
    b.close()
